export { QUESTIONS };
export const CATEGORY_MAP = Object.fromEntries(CATEGORIES.map(c => [c.id, c]));
export const LEVEL_MAP = Object.fromEntries(LEVELS.map(l => [l.n, l]));
export const QUESTIONS_BY_CATEGORY = Object.fromEntries(CATEGORIES.map(c => [c.id, QUESTIONS.filter(q => q.cat === c.id)]));
export const QUESTION_MAP = Object.fromEntries(QUESTIONS.map(q => [q.id, q]));

export function levelOf(n) {
  return LEVEL_MAP[n] || LEVELS[0];
}

export function rankForXp(xp) {
  let rank = RANKS[0];
  for (const r of RANKS) if (xp >= r.min) rank = r;
  const index = RANKS.indexOf(rank);
  const next = RANKS[index + 1] || null;
  return { ...rank, index, next, progress: next ? (xp - rank.min) / (next.min - rank.min) : 1 };
}

export function verseForDate(date = new Date()) {
  const key = date.getUTCFullYear() * 372 + (date.getUTCMonth() + 1) * 31 + date.getUTCDate();
  return VERSE_LIBRARY[key % VERSE_LIBRARY.length];
}

export function dailyQuestionIds(date = new Date()) {
  const key = date.getUTCFullYear() * 372 + (date.getUTCMonth() + 1) * 31 + date.getUTCDate();
  let seed = key * 2654435761 % 2147483647;
  const rand = () => {
    seed = (seed * 48271) % 2147483647;
    return seed / 2147483647;
  };
  const easy = QUESTIONS.filter(q => q.level === 1);
  const medium = QUESTIONS.filter(q => q.level === 2);
  const hard = QUESTIONS.filter(q => q.level === 3);
  const pick = (pool, n) => {
    const copy = [...pool];
    const out = [];
    while (out.length < n && copy.length) out.push(copy.splice(Math.floor(rand() * copy.length), 1)[0]);
    return out;
  };
  return [...pick(easy, 4), ...pick(medium, 4), ...pick(hard, 2)].map(q => q.id);
}

